@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap');
:root{--bg:#101619;--surface:#182124;--surface2:#1d292b;--line:#2c393a;--text:#e9eee8;--muted:#84928c;--gold:#e4b85c;--mint:#8cc9a5;--red:#e77566;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 48% -15%,#263431 0,transparent 45%),var(--bg);color:var(--text);font-family:var(--sans);min-height:100vh}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible{outline:2px solid var(--gold);outline-offset:3px}.app-shell{max-width:1440px;margin:auto;padding:0 40px}.topbar{height:80px;border-bottom:1px solid #ffffff0f;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;align-items:center;gap:11px;color:var(--text);text-decoration:none;min-width:195px}.brand-mark{width:37px;height:37px;border:1px solid #bd9852;border-radius:11px;color:var(--gold);display:grid;place-items:center;font-size:23px;background:#d8aa3b0d}.brand b,.brand small{display:block;letter-spacing:1.9px;font-size:12px}.brand small{font-size:9px;color:var(--gold);margin-top:3px;letter-spacing:2.7px}.main-nav{display:flex;align-items:center;gap:7px}.nav-btn{background:none;border:0;color:#91a099;border-radius:8px;padding:11px 15px;font-size:16px}.nav-btn span{font-size:12px;margin-left:5px}.nav-btn.active{background:#d6ad5714;color:var(--gold)}.wallet{display:flex;align-items:center;gap:12px}.wallet-item{height:35px;padding:0 8px;display:flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:8px;background:#172022;font-size:13px}.coin-icon,.gem-icon{color:var(--gold);font-size:16px}.gem-icon{color:#9bc6d0}.plus{border:0;background:transparent;color:var(--mint);font-size:19px;padding:0 2px}.icon-btn,.avatar{width:34px;height:34px;background:#202b2c;border:1px solid var(--line);border-radius:50%;color:#b4c0b9}.avatar{color:var(--gold)}main{min-height:calc(100vh - 139px);padding:36px 0 28px}.view{display:none}.view.active{display:block}.page-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:25px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;color:var(--gold);margin-bottom:8px}.page-heading h1{font:700 33px var(--serif);margin:0;letter-spacing:-.4px}.page-heading h1 em,.admin-modal h2 em{font-style:normal;color:var(--gold)}.page-heading p{margin:8px 0 0;color:var(--muted);font-size:13px}.stage-chip{height:34px;padding:0 13px;border:1px solid var(--line);border-radius:6px;display:flex;align-items:center;gap:9px;font-size:9px;letter-spacing:1.2px;color:#a6b0a9}.stage-chip b{color:var(--text)}.live-dot{width:6px;height:6px;background:var(--mint);border-radius:50%;box-shadow:0 0 8px var(--mint)}.divider{height:13px;border-left:1px solid var(--line);margin:0 3px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:17px}.panel{background:linear-gradient(145deg,#1b2527,#172023);border:1px solid var(--line);border-radius:10px;box-shadow:0 8px 30px #00000012}.battle-panel{overflow:hidden}.battle-top{height:61px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;border-bottom:1px solid #ffffff0c}.battle-label{display:flex;align-items:center;gap:11px}.map-icon{width:33px;height:33px;display:grid;place-items:center;border-radius:8px;background:#bc9b481a;color:var(--gold);font-size:19px}.battle-label b,.battle-label small{display:block}.battle-label b{font-size:12px}.battle-label small{color:var(--muted);font-size:10px;margin-top:3px}.battle-stats{display:flex;align-items:center;gap:20px;font-size:9px;letter-spacing:1px;color:#a0aaa3}.battle-stats b{color:var(--text);font-size:12px;margin-left:4px}.heart{color:#f18a7d;font-size:15px}.heart b{color:var(--text)}.speed-controls{display:flex;gap:5px}.speed-controls button{border:1px solid var(--line);background:#202b2c;border-radius:5px;color:#bdc6bf;padding:5px 8px;font-size:10px}.canvas-wrap{position:relative;background:#27382f;min-height:360px;aspect-ratio:1.88;overflow:hidden}canvas{display:block;width:100%;height:100%;position:absolute;inset:0}.battle-overlay{position:absolute;inset:0;background:#0d1712aa;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:20px;transition:opacity .25s}.battle-overlay.hidden{opacity:0;pointer-events:none}.overlay-icon{font-size:25px;color:var(--gold);margin-bottom:5px}.battle-overlay h2{font:700 22px var(--serif);margin:0}.battle-overlay p{font-size:11px;color:#c0c9bd;margin:8px 0 16px}.primary-btn{border:1px solid #edcb7c;background:linear-gradient(135deg,#d9af58,#b98b3e);color:#18201d;border-radius:6px;padding:11px 16px;font-size:10px;font-weight:700;letter-spacing:1px;box-shadow:0 5px 20px #c7993940}.primary-btn span{font-size:16px;margin-left:13px}.build-footer{padding:14px 16px 16px}.build-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:11px}.build-head b{font-size:10px;letter-spacing:1.5px}.build-head small{display:block;color:var(--muted);font-size:9px;margin-top:4px}.hint{font-size:9px;color:#9da99f}.tower-list{display:grid;grid-template-columns:repeat(5,minmax(80px,1fr));gap:7px}.tower-choice{position:relative;min-width:0;border:1px solid var(--line);background:#202b2c;border-radius:7px;padding:8px 7px;text-align:left;transition:.18s}.tower-choice:hover,.tower-choice.selected{border-color:var(--gold);background:#b89a4114;transform:translateY(-1px)}.tower-choice.disabled{opacity:.42}.tower-emoji{font-size:18px;display:block;margin-bottom:5px}.tower-choice b{display:block;font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tower-choice small{display:block;font-size:9px;color:var(--gold);margin-top:3px}.side-column{display:flex;flex-direction:column;gap:12px}.objective-card,.selected-card{padding:15px}.card-kicker{display:flex;justify-content:space-between;color:var(--gold);letter-spacing:1.3px;font-size:9px;font-weight:700}.card-kicker span{color:var(--muted);font-weight:500}.objective-card h3{font:600 16px var(--serif);margin:12px 0 5px}.objective-card p{color:var(--muted);font-size:10px;margin:0 0 14px}.quest-progress{height:5px;background:#2c3837;border-radius:8px;overflow:hidden}.quest-progress span{display:block;width:0;height:100%;background:var(--gold);transition:width .3s}.quest-foot{display:flex;justify-content:space-between;margin-top:8px;font-size:9px;color:var(--muted)}.quest-foot b{color:var(--gold)}.empty-select{height:130px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:#8d9991}.empty-select span{font-size:23px;color:#718079}.empty-select b{color:#c2cac2;font-size:11px;margin:9px 0 5px}.empty-select small{font-size:9px;max-width:160px;line-height:1.5}.tower-detail{padding-top:13px}.detail-title{display:flex;align-items:center;gap:10px}.detail-icon{font-size:26px}.detail-title b{display:block;font-size:12px}.detail-title small{color:var(--gold);font-size:9px}.detail-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:13px 0}.detail-stat{background:#202b2c;border-radius:6px;padding:8px}.detail-stat small,.detail-stat b{display:block}.detail-stat small{color:var(--muted);font-size:8px;text-transform:uppercase;letter-spacing:1px}.detail-stat b{font-size:11px;margin-top:3px}.detail-actions{display:flex;gap:7px}.small-btn{flex:1;background:#263331;color:var(--mint);border:1px solid #385347;border-radius:5px;padding:8px 4px;font-size:9px}.small-btn.sell{color:#e38d79;border-color:#69413a}.tip-card{display:flex;gap:10px;padding:12px}.tip-symbol{color:var(--gold);font-size:17px}.tip-card b{font-size:8px;letter-spacing:1px;color:#c8b276}.tip-card p{font-size:9px;line-height:1.5;color:var(--muted);margin:5px 0 0}.admin-link{background:none;border:0;color:#68766f;font-size:9px;align-self:flex-end}.canvas-toast{position:absolute;left:50%;top:14px;transform:translate(-50%,-10px);background:#101816eF;color:#f3d37e;border:1px solid #897440;border-radius:20px;padding:7px 13px;font-size:10px;opacity:0;transition:.2s;pointer-events:none}.canvas-toast.show{opacity:1;transform:translate(-50%,0)}.footer{height:45px;border-top:1px solid #ffffff0c;display:flex;align-items:center;justify-content:space-between;color:#69766f;font-size:8px;letter-spacing:1.2px}.footer i{color:var(--gold);padding:0 5px}.footer span:last-child{letter-spacing:0;font-size:9px;color:#80958a}
/* Market, summoning, heroes */
.shop-tabs{display:flex;gap:8px;border-bottom:1px solid var(--line);margin-bottom:19px}.shop-tab{background:none;border:0;color:var(--muted);padding:11px 14px;font-size:11px;border-bottom:2px solid transparent}.shop-tab.active{color:var(--gold);border-color:var(--gold)}.shop-grid,.collection-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.shop-item,.hero-card{padding:16px;min-height:190px;position:relative;overflow:hidden}.item-art{height:75px;border-radius:7px;background:radial-gradient(circle at 50% 100%,#b3883f33,transparent 65%),#202c2b;display:grid;place-items:center;font-size:38px;margin-bottom:13px}.item-name{font:600 15px var(--serif);margin:0 0 5px}.item-desc{font-size:10px;color:var(--muted);line-height:1.5;min-height:29px}.item-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:12px}.rarity{color:var(--gold);font-size:8px;text-transform:uppercase;letter-spacing:1px}.buy-btn{border:1px solid #526953;background:#24352e;color:var(--mint);border-radius:5px;padding:7px 10px;font-size:9px}.buy-btn:disabled{opacity:.5}.summon-layout{display:grid;grid-template-columns:1fr 1.15fr;gap:16px}.summon-art{min-height:340px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 38%,#254b50 0,#182a2b 40%,#172023 75%)}.summon-copy{position:absolute;z-index:2;left:28px;bottom:25px}.summon-copy>span{font-size:9px;letter-spacing:2px;color:#a6dad0}.summon-copy h2{font:700 29px var(--serif);line-height:1.1;margin:8px 0}.summon-copy p{font-size:10px;color:#a6b6b0}.portal-rune{position:absolute;left:50%;top:38%;transform:translate(-50%,-50%);font-size:98px;color:#a1e4d8;text-shadow:0 0 40px #44e6d9,0 0 90px #44e6d977;animation:pulse 3s infinite}.portal-orbit{position:absolute;left:50%;top:37%;border:1px solid #8ad5cc70;border-radius:50%;transform:translate(-50%,-50%) rotate(-24deg)}.orbit-a{width:230px;height:105px;animation:orbit 14s linear infinite}.orbit-b{width:190px;height:235px;transform:translate(-50%,-50%) rotate(54deg)}@keyframes pulse{50%{text-shadow:0 0 65px #44e6d9,0 0 120px #44e6d977;transform:translate(-50%,-50%) scale(1.05)}}@keyframes orbit{to{transform:translate(-50%,-50%) rotate(336deg)}}.banner-list{display:grid;grid-template-columns:1fr 1fr;gap:11px}.banner-card{padding:14px;display:flex;flex-direction:column;justify-content:space-between}.banner-card h3{font:600 15px var(--serif);margin:0}.banner-card p{font-size:9px;color:var(--muted);line-height:1.5}.banner-chances{font-size:8px;color:#b9c3ba;line-height:1.8}.banner-foot{display:flex;align-items:center;justify-content:space-between;margin-top:13px}.summon-btn{background:#354a41;border:1px solid #567d65;color:#b4dfbc;border-radius:5px;padding:8px 10px;font-size:9px}.probability-note{font-size:10px;color:var(--muted);margin-top:16px}.summon-result{display:none;position:absolute;inset:0;z-index:3;background:#101818ee;align-items:center;justify-content:center;flex-direction:column;text-align:center;animation:reveal .4s}.summon-result.show{display:flex}@keyframes reveal{from{opacity:0;transform:scale(.88)}to{opacity:1;transform:scale(1)}}.summon-result .result-icon{font-size:75px;filter:drop-shadow(0 0 25px #dfbe6e)}.summon-result h3{font:700 25px var(--serif);margin:6px}.summon-result p{font-size:10px;color:var(--gold)}.hero-card{min-height:170px}.hero-card .hero-emoji{float:right;font-size:40px}.hero-card h3{font:600 16px var(--serif);margin:12px 0 3px}.hero-card small{color:var(--gold);font-size:9px}.hero-card p{font-size:9px;color:var(--muted)}.hero-card .buy-btn{margin-top:6px}
/* dialogs */
.modal-backdrop,.admin-backdrop{position:fixed;inset:0;background:#050909c9;z-index:20;display:none;align-items:center;justify-content:center;padding:18px}.modal-backdrop.show,.admin-backdrop.show{display:flex}.modal{width:min(440px,100%);padding:24px;position:relative}.modal h2,.admin-modal h2{font:700 24px var(--serif);margin:0 0 8px}.modal p,.admin-modal>p{color:var(--muted);font-size:11px;line-height:1.6}.modal-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:18px}.secondary-btn{border:1px solid var(--line);border-radius:5px;background:#202a2b;color:#bdc6bf;padding:10px 14px;font-size:10px}.modal-close{position:absolute;right:13px;top:10px;border:0;background:none;color:#aeb8b0;font-size:22px}.admin-modal{width:min(400px,100%);padding:25px;position:relative}.admin-modal form{display:flex;gap:8px;margin-top:18px}.admin-modal input{flex:1;min-width:0;background:#111a1b;border:1px solid var(--line);border-radius:5px;padding:11px;color:var(--text)}.admin-modal .primary-btn{white-space:nowrap}.admin-tool-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:15px}.admin-tool-grid button{background:#25342e;border:1px solid #455b4d;color:#c9e6d0;border-radius:5px;padding:9px;font-size:10px}.admin-backdrop input:focus{outline:1px solid var(--gold)}
@media(max-width:980px){.app-shell{padding:0 22px}.game-layout{grid-template-columns:minmax(0,1fr) 230px;gap:12px}.tower-list{grid-template-columns:repeat(5,minmax(65px,1fr))}.tower-choice{padding:7px 5px}.tower-choice b{font-size:8px}.shop-grid,.collection-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:720px){.app-shell{padding:0 13px}.topbar{height:65px;gap:8px}.brand{min-width:auto}.brand-mark{width:32px;height:32px}.brand b{font-size:10px}.brand small{font-size:8px}.main-nav{position:fixed;z-index:10;bottom:0;left:0;right:0;height:57px;background:#121b1c;border-top:1px solid var(--line);justify-content:space-around;gap:0}.nav-btn{padding:8px 9px;font-size:15px}.nav-btn span{font-size:9px;margin-left:3px}.wallet{gap:5px}.wallet-item{height:30px;padding:0 5px;gap:4px;font-size:10px}.icon-btn{display:none}.avatar{width:29px;height:29px}.page-heading{align-items:flex-start;margin:25px 0 18px}.page-heading h1{font-size:27px}.page-heading p{font-size:11px;max-width:280px}.stage-chip{font-size:7px;padding:0 8px;white-space:nowrap}.game-layout{grid-template-columns:1fr}.side-column{display:grid;grid-template-columns:1fr 1fr}.objective-card{grid-column:span 2}.tip-card{grid-column:span 2}.admin-link{grid-column:span 2}.canvas-wrap{min-height:260px;aspect-ratio:1.25}.battle-top{padding:0 11px}.battle-stats{gap:9px}.tower-list{grid-template-columns:repeat(5,minmax(0,1fr));gap:5px}.tower-choice{padding:7px 5px}.tower-emoji{font-size:16px}.tower-choice b{font-size:7px}.tower-choice small{font-size:8px}.hint{display:none}.build-footer{padding:11px}.shop-tabs{overflow:auto}.shop-tab{white-space:nowrap;padding:10px}.shop-grid,.collection-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.shop-item{padding:11px;min-height:180px}.summon-layout{grid-template-columns:1fr}.summon-art{min-height:260px}.banner-list{gap:8px}.banner-card{padding:11px}.footer{margin-bottom:57px;height:40px}.footer span:first-child{font-size:7px}.footer span:last-child{font-size:8px}.probability-note{font-size:9px}.modal{padding:20px}}
@media(max-width:390px){.brand small{display:none}.wallet{gap:4px}.wallet-item{font-size:9px}.wallet .plus{font-size:15px}.nav-btn{padding:8px 6px}.nav-btn span{font-size:8px}.tower-choice b{font-size:6px}.tower-emoji{font-size:14px}.battle-stats{gap:6px}}

(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const SAVE_KEY='guardioes_reino_v1';
const towerDefs=[
 {id:'archer',name:'Arqueira',emoji:'🏹',cost:100,damage:16,rate:.72,range:132,color:'#e6c46c',desc:'Disparos rápidos e precisos.'},
 {id:'mage',name:'Mágica',emoji:'🔮',cost:145,damage:34,rate:1.35,range:148,color:'#b699fa',desc:'Energia arcana que ignora armadura.'},
 {id:'fire',name:'Fogo',emoji:'🔥',cost:180,damage:26,rate:1.55,range:115,color:'#ff8055',splash:50,desc:'Explosão de fogo em área.'},
 {id:'ice',name:'Gelo',emoji:'❄️',cost:160,damage:13,rate:1.15,range:140,color:'#83d9ec',slow:.58,desc:'Reduz a velocidade dos inimigos.'},
 {id:'electric',name:'Elétrica',emoji:'⚡',cost:230,damage:24,rate:1.18,range:158,color:'#a8e9ff',chain:3,desc:'Arcos saltam entre alvos.'},
 {id:'cannon',name:'Canhão',emoji:'💣',cost:260,damage:72,rate:2.3,range:125,color:'#dca269',splash:64,desc:'Projéteis lentos, explosões brutais.'},
 {id:'laser',name:'Laser',emoji:'☄️',cost:330,damage:12,rate:.22,range:177,color:'#ff567b',desc:'Feixe contínuo de alta precisão.'},
 {id:'shadow',name:'Sombria',emoji:'🌑',cost:390,damage:57,rate:1.55,range:154,color:'#bc84e4',desc:'Dano sombrio atravessa defesas.'},
 {id:'dragon',name:'Dragão',emoji:'🐉',cost:520,damage:58,rate:1.75,range:165,color:'#ff8a45',splash:75,desc:'Sopro flamejante de grande alcance.'},
 {id:'legend',name:'Lendária',emoji:'🌟',cost:740,damage:86,rate:1.2,range:190,color:'#f7df76',chain:2,splash:28,desc:'Poder ancestral, crítica devastadora.'}
];
const heroes=[
 {id:'warrior',name:'Guerreiro',emoji:'⚔️',rarity:'Comum',color:'#b8c2bd',damage:15,range:105,rate:.85,health:120,desc:'Combatente equilibrado da linha de frente.'},
 {id:'archer',name:'Arqueiro',emoji:'🧝',rarity:'Raro',color:'#7fd29b',damage:22,range:150,rate:1.05,health:85,desc:'Dispara flechas com grande alcance.'},
 {id:'mage',name:'Mago',emoji:'🧙',rarity:'Épico',color:'#b799f5',damage:38,range:145,rate:1.35,health:75,desc:'Magia explosiva contra grupos.'},
 {id:'knight',name:'Cavaleiro',emoji:'🛡️',rarity:'Raro',color:'#6fbae0',damage:17,range:95,rate:1.05,health:210,desc:'Resiste aos golpes e protege a retaguarda.'},
 {id:'ninja',name:'Ninja',emoji:'🥷',rarity:'Épico',color:'#d08cf5',damage:18,range:115,rate:.48,health:90,desc:'Ataques velozes e críticos.'},
 {id:'dragon',name:'Dragão',emoji:'🐲',rarity:'Lendário',color:'#ed9a58',damage:55,range:150,rate:1.4,health:180,desc:'Sopro de fogo em área.'},
 {id:'demon',name:'Rei Demônio',emoji:'👹',rarity:'Secreto',color:'#ed6680',damage:92,range:165,rate:1.25,health:260,desc:'Uma força mítica que dobra a realidade.'},
 {id:'oracle',name:'Oráculo Astral',emoji:'🪄',rarity:'Mítico',color:'#e4ce71',damage:65,range:180,rate:1.1,health:140,desc:'Vê o futuro e atinge todos os alvos.'}
];
const initial={gold:1250,gems:80,wave:0,lives:20,highWave:0,unlocked:towerDefs.map(t=>t.id),ownedHeroes:{warrior:1},heroLevels:{},essence:0,quests:0,achievements:[],skin:'default'};
let data=loadData(),game={running:false,paused:false,wave:0,lives:20,enemies:[],towers:[],effects:[],spawnLeft:0,spawnTimer:0,selectedBuild:null,selectedTower:null,heroMode:null,speed:1,gameOver:false,lastTime:0,canvas:null,ctx:null,frame:0};
function loadData(){try{return {...initial,...JSON.parse(localStorage.getItem(SAVE_KEY)||'{}')}}catch{return {...initial}}}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(data));$('#saveStatus').textContent='✓ Progresso salvo automaticamente';}catch{$('#saveStatus').textContent='⚠ Não foi possível salvar neste navegador';}}
const fmt=n=>Math.floor(n).toLocaleString('pt-BR');
function wallet(){ $('#gold').textContent=fmt(data.gold);$('#gems').textContent=fmt(data.gems);$('#waveLabel').textContent=game.running?game.wave:data.highWave;$('#livesLabel').textContent=game.running?game.lives:data.lives;$('#questProgress').style.width=`${Math.min(100,data.quests/5*100)}%`;$('#questText').textContent=`${Math.min(5,data.quests)} / 5 ondas`;$('#collectionCount').textContent=Object.values(data.ownedHeroes).reduce((a,b)=>a+b,0); }
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1900)}
function switchView(name){$$('.view').forEach(v=>v.classList.remove('active'));$('#'+name+'View').classList.add('active');$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='shop')renderShop();if(name==='summon')renderBanners();if(name==='collection')renderCollection();}
$$('.nav-btn').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
$$('.wallet .plus').forEach(b=>b.addEventListener('click',()=>switchView('shop')));

