function pathPoints(){return [[-25,232],[126,232],[126,115],[312,115],[312,352],[492,352],[492,170],[674,170],[674,302],[926,302]]}
let route=pathPoints(),routeSegments=[],routeLength=0;function buildRoute(){routeSegments=[];routeLength=0;for(let i=1;i<route.length;i++){const a=route[i-1],b=route[i],len=Math.hypot(b[0]-a[0],b[1]-a[1]);routeSegments.push({a,b,len,start:routeLength});routeLength+=len}}buildRoute();
function posOnRoute(progress){const dist=progress*routeLength;const s=routeSegments.find(x=>dist<=x.start+x.len)||routeSegments.at(-1),q=Math.min(1,Math.max(0,(dist-s.start)/s.len));return [s.a[0]+(s.b[0]-s.a[0])*q,s.a[1]+(s.b[1]-s.a[1])*q]}
function initCanvas(){const c=$('#gameCanvas');game.canvas=c;game.ctx=c.getContext('2d');const resize=()=>{const r=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);game.ctx.setTransform(c.width/900,0,0,c.height/480,0,0);draw()};new ResizeObserver(resize).observe(c);resize();c.addEventListener('click',canvasClick);requestAnimationFrame(loop)}
