// grassy tiles and subtle texture
for(let y=0;y<480;y+=42)for(let x=0;x<900;x+=48){c.fillStyle=((x/48+y/42)%2)?'#38513e':'#354d3b';c.fillRect(x,y,48,42);}
// glowy woodland clearing
const grad=c.createRadialGradient(450,235,20,450,235,460);grad.addColorStop(0,'#50644722');grad.addColorStop(1,'#0c1a1328');c.fillStyle=grad;c.fillRect(0,0,900,480);
// decorative shrubs & stones, deterministic
for(let i=0;i<42;i++){const x=(i*173+57)%890,y=(i*97+21)%470;if(routeDistance(x,y)<48)continue;c.fillStyle=i%3?'#1f382c':'#263b31';c.beginPath();c.ellipse(x,y,8+(i%4)*2,4+(i%3)*2,-.25,0,Math.PI*2);c.fill();c.fillStyle='#5e7650';c.beginPath();c.arc(x-2,y-2,2,0,Math.PI*2);c.fill()}
// pathway shadow and stones
