// entry and crystal
c.fillStyle='#8c493c';c.beginPath();c.arc(22,232,18,0,7);c.fill();c.fillStyle='#ed9980';c.font='bold 15px sans-serif';c.fillText('!',17,238);c.fillStyle='#6ccbc3';c.shadowColor='#69f2dd';c.shadowBlur=15;c.beginPath();c.moveTo(875,284);c.lineTo(891,302);c.lineTo(875,320);c.lineTo(859,302);c.closePath();c.fill();c.shadowBlur=0;
