function loop(ts){const dt=Math.min(.05,(ts-(game.lastTime||ts))/1000);game.lastTime=ts;update(dt);draw();requestAnimationFrame(loop)}
function upgrade(t){if(t.kind==='hero'){const id=t.heroId,level=data.heroLevels[id]||1,cost=110*level;if(data.gold<cost){toast('Moedas insuficientes para evoluir.');return}data.gold-=cost;data.heroLevels[id]=level+1;t.level=level+1;t.damage=Math.round(t.damage*1.24);t.maxHp=Math.round(t.maxHp*1.18);t.hp=t.maxHp;t.upgradeCost=110*(level+1);toast(`${heroes.find(h=>h.id===id).name} evoluiu para o nível ${level+1}!`)}else{if(data.gold<t.upgradeCost){toast('Moedas insuficientes para evoluir.');return}data.gold-=t.upgradeCost;t.invested+=t.upgradeCost;t.level++;t.damage=Math.round(t.damage*1.34);t.range=Math.round(t.range*1.08);t.rate=Math.max(.16,t.rate*.94);t.upgradeCost=Math.round(t.upgradeCost*1.62);toast(`Torre evoluiu para o nível ${t.level}!`)}save();wallet();renderBuild();renderSelected();draw()}
function sellTower(t){if(t.kind==='hero'){game.towers=game.towers.filter(x=>x!==t);toast('Defensor retirado do campo.')}else{const refund=Math.floor(t.invested*.62);data.gold+=refund;game.towers=game.towers.filter(x=>x!==t);toast(`Torre vendida por ${fmt(refund)} moedas.`)}game.selectedTower=null;save();wallet();renderBuild();renderSelected();draw()}
let shopCategory='towers';$$('.shop-tab').forEach(b=>b.onclick=()=>{$$('.shop-tab').forEach(x=>x.classList.toggle('active',x===b));shopCategory=b.dataset.shop;renderShop()});
function renderShop(){const grid=$('#shopGrid');let items=[];if(shopCategory==='towers'){items=towerDefs.map(t=>({id:'tower-'+t.id,title:`Projeto: ${t.name}`,emoji:t.emoji,desc:`${t.desc} Dano ${t.damage} · alcance ${t.range}.`,rarity:'Projeto de defesa',price:Math.ceil(t.cost*1.15),currency:'gold',owned:data.unlocked.includes(t.id),kind:'tower'}))}
