if(shopCategory==='coins'){items=[['small','Pacote Pequeno','1.000 moedas por 40 gemas','🪙',40,1000],['medium','Pacote Médio','3.000 moedas por 100 gemas','💰',100,3000],['large','Pacote Grande','8.000 moedas por 250 gemas','🧰',250,8000],['giant','Pacote Gigante','20.000 moedas por 500 gemas','🏆',500,20000],['supreme','Pacote Supremo','50.000 moedas por 1.000 gemas','✨',1000,50000]].map(([id,title,desc,emoji,price,amount])=>({id,title,desc,emoji,rarity:'Câmbio de gemas',price,currency:'gems',kind:'coins',amount}))}
