{id:'warrior',name:'Guerreiro',emoji:'⚔️',rarity:'Comum',color:'#b8c2bd',damage:15,range:105,rate:.85,hp:120,desc:'Combatente de linha de frente.'},
{id:'archer',name:'Arqueiro',emoji:'🧝',rarity:'Raro',color:'#7fd29b',damage:22,range:150,rate:1.05,hp:85,desc:'Flechas de grande alcance.'},
