let G={running:false,paused:false,gameOver:false,wave:0,lives:20,spawnLeft:0,spawnTimer:0,enemies:[],units:[],effects:[],build:null,hero:null,selected:null,speed:1,last:0};
const route=[[-30,232],[126,232],[126,115],[312,115],[312,352],[492,352],[492,170],[674,170],[674,302],[930,302]];
let seg=[],total=0;route.forEach((p,i)=>{if(i){const a=route[i-1],len=Math.hypot(p[0]-a[0],p[1]-a[1]);seg.push({a,b:p,len,start:total});total+=len}});
function pos(p){const dist=p*total,s=seg.find(x=>dist<=x.start+x.len)||seg.at(-1),q=Math.max(0,Math.min(1,(dist-s.start)/s.len));return[s.a[0]+(s.b[0]-s.a[0])*q,s.a[1]+(s.b[1]-s.a[1])*q]}
function routeDist(x,y){let m=Infinity;for(const s of seg){const vx=s.b[0]-s.a[0],vy=s.b[1]-s.a[1],t=Math.max(0,Math.min(1,((x-s.a[0])*vx+(y-s.a[1])*vy)/(s.len*s.len)));m=Math.min(m,Math.hypot(x-(s.a[0]+vx*t),y-(s.a[1]+vy*t)))}return m}

function renderBuild(){const root=$('#towerList');root.innerHTML=towers.map(t=>`<button class="tower-choice ${G.build===t.id?'selected':''}" data-tower="${t.id}"><span class="tower-emoji">${t.emoji}</span><b>${t.name}</b><small>◉ ${fmt(t.cost)}</small></button>`).join('');root.querySelectorAll('[data-tower]').forEach(b=>b.onclick=()=>{G.build=b.dataset.tower;G.hero=null;G.selected=null;renderBuild();toast('Clique no terreno para posicionar a torre.')});let box=root.parentElement.querySelector('.hero-build-list');if(!box){const extra=document.createElement('div');extra.className='hero-build-list';extra.innerHTML=Object.keys(data.ownedHeroes).filter(id=>data.ownedHeroes[id]>0).map(id=>{const h=heroes.find(x=>x.id===id);return `<button class="tower-choice hero-choice ${G.hero===id?'selected':''}" data-hero="${id}"><span class="tower-emoji">${h.emoji}</span><b>${h.name}</b><small>${h.rarity}</small></button>`}).join('');extra.style.display='grid';extra.style.gridTemplateColumns='repeat(auto-fill,minmax(88px,1fr))';extra.style.gap='7px';extra.style.marginTop='7px';root.after(extra)}else{box.innerHTML=Object.keys(data.ownedHeroes).filter(id=>data.ownedHeroes[id]>0).map(id=>{const h=heroes.find(x=>x.id===id);return `<button class="tower-choice hero-choice ${G.hero===id?'selected':''}" data-hero="${id}"><span class="tower-emoji">${h.emoji}</span><b>${h.name}</b><small>${h.rarity}</small></button>`}).join('')}
box=root.parentElement.querySelector('.hero-build-list');box.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{G.hero=b.dataset.hero;G.build=null;G.selected=null;renderBuild();toast('Clique no terreno para posicionar o defensor.')})}

