'use strict';
const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];
const KEY = 'guardioes_reino_v1';
const towers = [
 {id:'archer',name:'Arqueira',emoji:'🏹',cost:100,damage:16,rate:.72,range:132,color:'#e6c46c',special:'Rápida'},
 {id:'mage',name:'Mágica',emoji:'🔮',cost:145,damage:34,rate:1.35,range:148,color:'#b699fa',special:'Arcana'},
 {id:'fire',name:'Fogo',emoji:'🔥',cost:180,damage:26,rate:1.55,range:115,color:'#ff8055',splash:50,special:'Área'},
 {id:'ice',name:'Gelo',emoji:'❄️',cost:160,damage:13,rate:1.15,range:140,color:'#83d9ec',slow:.58,special:'Lentidão'},
 {id:'electric',name:'Elétrica',emoji:'⚡',cost:230,damage:24,rate:1.18,range:158,color:'#a8e9ff',chain:3,special:'Ricochete'},
 {id:'cannon',name:'Canhão',emoji:'💣',cost:260,damage:72,rate:2.3,range:125,color:'#dca269',splash:64,special:'Explosão'},
 {id:'laser',name:'Laser',emoji:'☄️',cost:330,damage:12,rate:.22,range:177,color:'#ff567b',special:'Contínuo'},
 {id:'shadow',name:'Sombria',emoji:'🌑',cost:390,damage:57,rate:1.55,range:154,color:'#bc84e4',special:'Sombrio'},
 {id:'dragon',name:'Dragão',emoji:'🐉',cost:520,damage:58,rate:1.75,range:165,color:'#ff8a45',splash:75,special:'Sopro'},
 {id:'legend',name:'Lendária',emoji:'🌟',cost:740,damage:86,rate:1.2,range:190,color:'#f7df76',chain:2,splash:28,special:'Ancestral'}
];
const heroes = [
 {id:'warrior',name:'Guerreiro',emoji:'⚔️',rarity:'Comum',color:'#b8c2bd',damage:15,range:105,rate:.85,hp:120,desc:'Combatente de linha de frente.'},
 {id:'archer',name:'Arqueiro',emoji:'🧝',rarity:'Raro',color:'#7fd29b',damage:22,range:150,rate:1.05,hp:85,desc:'Flechas de grande alcance.'},
 {id:'mage',name:'Mago',emoji:'🧙',rarity:'Épico',color:'#b799f5',damage:38,range:145,rate:1.35,hp:75,desc:'Magia explosiva contra grupos.'},
 {id:'knight',name:'Cavaleiro',emoji:'🛡️',rarity:'Raro',color:'#6fbae0',damage:17,range:95,rate:1.05,hp:210,desc:'Protege a retaguarda.'},
 {id:'ninja',name:'Ninja',emoji:'🥷',rarity:'Épico',color:'#d08cf5',damage:18,range:115,rate:.48,hp:90,desc:'Ataques velozes.'},
 {id:'dragon',name:'Dragão',emoji:'🐲',rarity:'Lendário',color:'#ed9a58',damage:55,range:150,rate:1.4,hp:180,desc:'Sopro de fogo em área.'},
 {id:'demon',name:'Rei Demônio',emoji:'👹',rarity:'Secreto',color:'#ed6680',damage:92,range:165,rate:1.25,hp:260,desc:'Força mística devastadora.'},
 {id:'oracle',name:'Oráculo Astral',emoji:'🪄',rarity:'Mítico',color:'#e4ce71',damage:65,range:180,rate:1.1,hp:140,desc:'Prevê ataques e atinge todos.'}
];
const initial = {gold:1250,gems:80,highWave:0,lives:20,unlocked:towers.map(t=>t.id),ownedHeroes:{warrior:1},heroLevels:{},essence:0,quests:0,skin:'default',admin:false};
let data; try { data={...initial,...JSON.parse(localStorage.getItem(KEY)||'{}')}; if(!data.ownedHeroes)data.ownedHeroes={warrior:1}; } catch { data={...initial}; }
function save(){localStorage.setItem(KEY,JSON.stringify(data)); $('#saveStatus').textContent='✓ Progresso salvo automaticamente';}
const fmt=n=>Math.floor(n).toLocaleString('pt-BR');
function wallet(){['gold','gems'].forEach(k=>$('#'+k).textContent=fmt(data[k]));$('#questProgress').style.width=Math.min(100,(data.quests||0)/5*100)+'%';$('#questText').textContent=Math.min(5,data.quests||0)+' / 5 ondas';$('#collectionCount').textContent=Object.values(data.ownedHeroes).reduce((a,b)=>a+b,0);}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),1800);}
function switchView(name){$$('.view').forEach(v=>v.classList.remove('active'));$('#'+name+'View').classList.add('active');$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(name==='shop')renderShop();if(name==='summon')renderBanners();if(name==='collection')renderCollection();}
$$('.nav-btn').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$$('.wallet .plus').forEach(b=>b.onclick=()=>switchView('shop'));

let G={running:false,paused:false,wave:0,lives:20,spawnLeft:0,spawnTimer:0,enemies:[],units:[],effects:[],build:null,hero:null,selected:null,speed:1,last:0};
const route=[[-30,232],[126,232],[126,115],[312,115],[312,352],[492,352],[492,170],[674,170],[674,302],[930,302]];
let seg=[],total=0; route.forEach((p,i)=>{if(i){const a=route[i-1],len=Math.hypot(p[0]-a[0],p[1]-a[1]);seg.push({a,b:p,len,start:total});total+=len;}});
function pos(p){const dist=p*total,s=seg.find(x=>dist<=x.start+x.len)||seg.at(-1),q=Math.max(0,Math.min(1,(dist-s.start)/s.len));return[s.a[0]+(s.b[0]-s.a[0])*q,s.a[1]+(s.b[1]-s.a[1])*q];}
function routeDist(x,y){let m=Infinity;for(const s of seg){const vx=s.b[0]-s.a[0],vy=s.b[1]-s.a[1],t=Math.max(0,Math.min(1,((x-s.a[0])*vx+(y-s.a[1])*vy)/(s.len*s.len)));m=Math.min(m,Math.hypot(x-(s.a[0]+vx*t),y-(s.a[1]+vy*t)));}return m;}

function renderBuild(){const root=$('#towerList');root.innerHTML=towers.map(t=>`<button class="tower-choice ${G.build===t.id?'selected':''}" data-tower="${t.id}"><span class="tower-emoji">${t.emoji}</span><b>${t.name}</b><small>◉ ${fmt(t.cost)}</small></button>`).join('');root.querySelectorAll('[data-tower]').forEach(b=>b.onclick=()=>{G.build=b.dataset.tower;G.hero=null;G.selected=null;renderBuild();toast('Clique no terreno para posicionar a torre.');});let box=root.parentElement.querySelector('.hero-build-list');if(!box){box=document.createElement('div');box.className='hero-build-list';root.after(box);}box.style.display='grid';box.style.gridTemplateColumns='repeat(auto-fill,minmax(88px,1fr))';box.style.gap='7px';box.style.marginTop='7px';box.innerHTML=Object.keys(data.ownedHeroes).filter(id=>data.ownedHeroes[id]>0).map(id=>{const h=heroes.find(x=>x.id===id);return `<button class="tower-choice hero-choice ${G.hero===id?'selected':''}" data-hero="${id}"><span class="tower-emoji">${h.emoji}</span><b>${h.name}</b><small>${h.rarity}</small></button>`}).join('');box.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>{G.hero=b.dataset.hero;G.build=null;G.selected=null;renderBuild();toast('Clique no terreno para posicionar o defensor.')});}

function initCanvas(){const c=$('#gameCanvas');G.canvas=c;G.ctx=c.getContext('2d');function resize(){const r=c.getBoundingClientRect(),d=2;c.width=r.width*d;c.height=r.height*d;G.ctx.setTransform(c.width/900,0,0,c.height/480,0,0);}new ResizeObserver(resize).observe(c);resize();c.onclick=canvasClick;requestAnimationFrame(loop);}
function canvasClick(ev){const r=G.canvas.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width*900,y=(ev.clientY-r.top)/r.height*480;if(G.build||G.hero){if(routeDist(x,y)<34){toast('A rota precisa ficar livre!');return;}const occupied=G.units.some(u=>Math.hypot(u.x-x,u.y-y)<42);if(occupied){toast('Este local já está ocupado.');return;}if(G.build){const t=towers.find(a=>a.id===G.build);if(data.gold<t.cost){toast('Moedas insuficientes.');return;}data.gold-=t.cost;G.units.push({kind:'tower',id:t.id,x,y,level:1,cooldown:0,t});toast(t.name+' construída!');}else{const h=heroes.find(a=>a.id===G.hero);G.units.push({kind:'hero',id:h.id,x,y,level:data.heroLevels[h.id]||1,cooldown:0,h});toast(h.name+' posicionado!');}save();wallet();G.build=null;G.hero=null;renderBuild();renderSelected();return;}const u=G.units.find(a=>Math.hypot(a.x-x,a.y-y)<30);G.selected=u||null;renderSelected();}
function renderSelected(){const box=$('#selectedCard');if(!G.selected){box.innerHTML='<div class="card-kicker">UNIDADE SELECIONADA</div><div class="empty-select"><span>⌖</span><b>Nenhuma unidade</b><small>Construa uma defesa para ver seus detalhes.</small></div>';return;}const u=G.selected,a=u.kind==='tower'?u.t:u.h;const cost=Math.round((a.cost||100)*(0.55+u.level*.25)),upgrade=a.cost?Math.round(a.cost*(.45+u.level*.45)):80;box.innerHTML=`<div class="card-kicker">UNIDADE SELECIONADA</div><div class="selected-unit"><span>${a.emoji}</span><div><b>${a.name}</b><small>Nível ${u.level} • ${a.special||a.rarity}</small></div></div><div class="modal-actions"><button class="secondary-btn" id="sellUnit">Vender ◉ ${cost}</button><button class="buy-btn" id="upgradeUnit">Evoluir ◉ ${upgrade}</button></div>`;$('#sellUnit').onclick=()=>{data.gold+=cost;G.units=G.units.filter(v=>v!==u);G.selected=null;save();wallet();renderSelected();toast('Unidade vendida.')};$('#upgradeUnit').onclick=()=>{if(data.gold<upgrade){toast('Moedas insuficientes.');return;}data.gold-=upgrade;u.level++;save();wallet();renderSelected();toast('Unidade evoluída!')};}
function draw(){const c=G.ctx;c.clearRect(0,0,900,480);let g=c.createLinearGradient(0,0,900,480);g.addColorStop(0,'#283d31');g.addColorStop(1,'#1a2924');c.fillStyle=g;c.fillRect(0,0,900,480);c.globalAlpha=.12;c.fillStyle='#9db28a';for(let i=0;i<65;i++){let x=(i*137)%900,y=(i*i*31)%480;c.beginPath();c.arc(x,y,2+(i%3),0,7);c.fill();}c.globalAlpha=1;c.lineJoin='round';c.lineCap='round';c.strokeStyle='#4a5550';c.lineWidth=48;c.beginPath();route.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1]));c.stroke();c.strokeStyle='#77705a';c.lineWidth=41;c.stroke();c.strokeStyle='#958d70';c.lineWidth=2;c.setLineDash([8,12]);c.stroke();c.setLineDash([]);c.fillStyle='#94bd83';for(let i=0;i<18;i++){c.beginPath();c.arc((i*163+40)%900,(i*97+35)%480,5,0,7);c.fill();}c.fillStyle='#5e82ba';c.beginPath();c.arc(872,302,32,0,7);c.fill();c.fillStyle='#9adff1';c.beginPath();c.arc(872,302,18,0,7);c.fill();G.units.forEach(u=>{c.save();c.translate(u.x,u.y);c.fillStyle=u.kind==='tower'?u.t.color:u.h.color;c.beginPath();c.arc(0,0,18,0,7);c.fill();c.fillStyle='#172022';c.fillRect(-14,-25,28,7);c.fillStyle='#e4b85c';c.fillRect(-12,-23,24*((u.level-1)/4+.5),3);c.font='21px sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(u.kind==='tower'?u.t.emoji:u.h.emoji,0,1);c.restore();});G.enemies.forEach(e=>{const [x,y]=pos(e.progress);c.fillStyle=e.boss?'#b34f56':'#b9a08b';c.beginPath();c.arc(x,y,e.boss?17:12,0,7);c.fill();c.fillStyle='#6d1518';c.fillRect(x-15,y-20,30,4);c.fillStyle='#e77566';c.fillRect(x-15,y-20,30*Math.max(0,e.hp/e.maxHp),4);});G.effects.forEach(f=>{c.globalAlpha=Math.max(0,f.life/f.max);c.strokeStyle=f.color||'#fff';c.beginPath();c.moveTo(f.x1,f.y1);c.lineTo(f.x2,f.y2);c.stroke();c.globalAlpha=1;});}
function spawnEnemy(){const boss=G.wave>0&&G.wave%5===0&&G.spawnLeft===1;G.enemies.push({progress:0,hp:(45+G.wave*22)*(boss?3.2:1),maxHp:(45+G.wave*22)*(boss?3.2:1),speed:(28+G.wave*1.8)*(boss?.72:1),boss,reward:boss?40:8+G.wave*2});G.spawnLeft--;}
function hitEnemy(e,dmg){e.hp-=dmg;if(e.hp<=0){const i=G.enemies.indexOf(e);if(i>=0){G.enemies.splice(i,1);data.gold+=e.reward;wallet();save();G.effects.push({x1:pos(e.progress)[0],y1:pos(e.progress)[1],x2:pos(e.progress)[0],y2:pos(e.progress)[1],life:.25,max:.25,color:'#e4b85c'});}}}
function update(dt){if(!G.running||G.paused)return;G.spawnTimer-=dt;if(G.spawnLeft>0&&G.spawnTimer<=0){spawnEnemy();G.spawnTimer=Math.max(.28,1-G.wave*.035);}G.enemies.forEach(e=>e.progress+=dt*e.speed/total);for(let i=G.enemies.length-1;i>=0;i--)if(G.enemies[i].progress>=1){G.lives-=G.enemies[i].boss?3:1;G.enemies.splice(i,1);$('#livesLabel').textContent=G.lives;if(G.lives<=0)return gameOver();}G.units.forEach(u=>{u.cooldown-=dt;const base=u.kind==='tower'?u.t:u.h;if(u.cooldown<=0){let target=null,best=-1;G.enemies.forEach(e=>{const [x,y]=pos(e.progress),d=Math.hypot(u.x-x,u.y-y);if(d<=base.range*(1+(u.level-1)*.06)&&e.progress>best){target=e;best=e.progress;}});if(target){u.cooldown=base.rate*(.92**(u.level-1));const [tx,ty]=pos(target.progress),dmg=base.damage*(1+(u.level-1)*.22);G.effects.push({x1:u.x,y1:u.y,x2:tx,y2:ty,life:.16,max:.16,color:base.color});if(base.splash)G.enemies.slice().forEach(e=>{const [x,y]=pos(e.progress);if(Math.hypot(tx-x,ty-y)<=base.splash)hitEnemy(e,dmg*.75);});else if(base.chain){const sorted=G.enemies.slice().sort((a,b)=>Math.hypot(pos(a.progress)[0]-tx,pos(a.progress)[1]-ty)-Math.hypot(pos(b.progress)[0]-tx,pos(b.progress)[1]-ty));sorted.slice(0,base.chain).forEach((e,i)=>hitEnemy(e,dmg*(i?0.7:1)));}else hitEnemy(target,dmg);if(base.slow)target.slow=(target.slow||1)*.58;}}});G.effects.forEach(f=>f.life-=dt);G.effects=G.effects.filter(f=>f.life>0);if(G.spawnLeft===0&&G.enemies.length===0&&G.running){G.running=false;G.wave++;data.highWave=Math.max(data.highWave,G.wave);data.quests=Math.max(data.quests,G.wave);if(G.wave===5&&!data.questReward){data.questReward=true;data.gold+=350;}save();wallet();$('#waveLabel').textContent=G.wave;$('#battleOverlay').classList.add('show');$('#battleOverlay').querySelector('h2').textContent='Onda concluída';$('#battleOverlay').querySelector('p').textContent=`Você protegeu a clareira na onda ${G.wave}.`;$('#battleSub').textContent='Prepare a próxima defesa';}}
function loop(now){let dt=Math.min(.04,(now-G.last)/1000||0)*G.speed;G.last=now;update(dt);draw();requestAnimationFrame(loop);}
function startWave(){if(G.running)return;if(G.lives<=0)G.lives=20;G.running=true;G.paused=false;G.wave++;G.spawnLeft=6+G.wave*3;G.spawnTimer=.5;$('#waveLabel').textContent=G.wave;$('#livesLabel').textContent=G.lives;$('#battleOverlay').classList.remove('show');$('#battleSub').textContent='A batalha está em andamento';toast('Onda '+G.wave+' iniciada!');}
function gameOver(){G.running=false;G.lives=0;$('#livesLabel').textContent='0';$('#battleOverlay').classList.add('show');$('#battleOverlay').querySelector('h2').textContent='A linha foi rompida';$('#battleOverlay').querySelector('p').textContent='Reorganize suas defesas e tente novamente.';G.enemies=[];G.units=[];G.build=null;G.hero=null;save();}

function openModal(html){$('#modal').innerHTML=html+'<button class="modal-close" onclick="document.querySelector(\'#modalBackdrop\').classList.remove(\'show\')">×</button>';$('#modalBackdrop').classList.add('show');}
function renderShop(){const tab=document.querySelector('.shop-tab.active')?.dataset.shop||'towers',root=$('#shopGrid');let items=[];if(tab==='towers')items=towers.map(t=>({art:t.emoji,name:t.name,desc:t.special+' • '+t.damage+' dano • alcance '+t.range,price:t.cost,kind:'tower',id:t.id,rarity:'Defesa'}));if(tab==='characters')items=heroes.map(h=>({art:h.emoji,name:h.name,desc:h.desc,price:[{'Comum':300,'Raro':500,'Épico':800,'Lendário':1200,'Secreto':1800,'Mítico':2400}[h.rarity]||600],kind:'hero',id:h.id,rarity:h.rarity}));if(tab==='coins')items=[{art:'◉',name:'Bolsa de moedas',desc:'750 moedas para suas defesas.',price:80,kind:'coins',amount:750,rarity:'Pacote'},{art:'◉◉',name:'Baú de moedas',desc:'2.500 moedas para suas defesas.',price:220,kind:'coins',amount:2500,rarity:'Pacote'},{art:'♛',name:'Tesouro real',desc:'6.000 moedas para suas defesas.',price:480,kind:'coins',amount:6000,rarity:'Pacote'}];if(tab==='special')items=[{art:'✦',name:'Essência ancestral',desc:'Adiciona 40 essências de evolução.',price:150,kind:'essence',amount:40,rarity:'Especial'}];root.innerHTML=items.map((it,i)=>`<article class="shop-item panel"><div class="item-art">${it.art}</div><div class="rarity">${it.rarity}</div><h3 class="item-name">${it.name}</h3><p class="item-desc">${it.desc}</p><div class="item-bottom"><b>${tab==='coins'||tab==='special'?'◆':'◉'} ${fmt(it.price)}</b><button class="buy-btn" data-item="${i}">ADQUIRIR</button></div></article>`).join('');root.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>buyItem(items[+b.dataset.item],tab));}
function buyItem(it,tab){const useGems=tab==='coins'||tab==='special';if(useGems?data.gems<it.price:data.gold<it.price){toast('Saldo insuficiente.');return;}if(useGems)data.gems-=it.price;else data.gold-=it.price;if(it.kind==='tower'&&!data.unlocked.includes(it.id))data.unlocked.push(it.id);if(it.kind==='hero'){data.ownedHeroes[it.id]=(data.ownedHeroes[it.id]||0)+1;}if(it.kind==='coins')data.gold+=it.amount;if(it.kind==='essence')data.essence+=it.amount;save();wallet();renderBuild();toast(it.name+' adquirido!');}
$$('.shop-tab').forEach(b=>b.onclick=()=>{$$('.shop-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderShop();});
function renderBanners(){const root=$('#bannerList');root.innerHTML=`<article class="banner-card panel"><div class="rarity">INVOCAR HERÓIS</div><h3>Uma vez</h3><p>Probabilidades: Comum 55% • Raro 25% • Épico 15% • Superior 5%</p><button class="buy-btn" id="summonOne">◆ 80</button></article><article class="banner-card panel"><div class="rarity">INVOCAR HERÓIS</div><h3>Chamada ×10</h3><p>10 invocações independentes com chances iguais.</p><button class="buy-btn" id="summonTen">◆ 720</button></article>`;$('#summonOne').onclick=()=>summon(1);$('#summonTen').onclick=()=>summon(10);}
function summon(count){const cost=count===1?80:720;if(data.gems<cost){toast('Gemas insuficientes.');return;}data.gems-=cost;const got=[];for(let i=0;i<count;i++){const r=Math.random();let pool=heroes.filter(h=>h.rarity==='Comum'||h.rarity==='Raro');if(r<.55)pool=heroes.filter(h=>h.rarity==='Comum'||h.rarity==='Raro'&&h.id==='warrior'||h.rarity==='Raro');else if(r<.80)pool=heroes.filter(h=>h.rarity==='Raro'||h.rarity==='Épico');else if(r<.95)pool=heroes.filter(h=>h.rarity==='Épico'||h.rarity==='Lendário');else pool=heroes.filter(h=>h.rarity==='Secreto'||h.rarity==='Mítico'||h.rarity==='Lendário');const h=pool[Math.floor(Math.random()*pool.length)]||heroes[0];if(data.ownedHeroes[h.id]){data.ownedHeroes[h.id]++;data.essence+=10;}else data.ownedHeroes[h.id]=1;got.push(h);}save();wallet();renderBuild();renderCollection();$('#summonResult').innerHTML=got.map(h=>`<span title="${h.name}" style="color:${h.color}">${h.emoji}</span>`).join('');toast(got.length===1?got[0].name+' invocado!':got.length+' heróis invocados!');}
function renderCollection(){const root=$('#collectionGrid');root.innerHTML=Object.entries(data.ownedHeroes).map(([id,n])=>{const h=heroes.find(x=>x.id===id);if(!h)return '';const lv=data.heroLevels[id]||1;return `<article class="hero-card panel"><div class="item-art" style="background:radial-gradient(circle,#${h.color.slice(1)}33,transparent 70%),#202c2b">${h.emoji}</div><div class="rarity">${h.rarity}</div><h3 class="item-name">${h.name}</h3><p class="item-desc">${h.desc}<br><b>Nível ${lv} • ${n} cópia${n>1?'s':''}</b></p><div class="item-bottom"><button class="buy-btn" data-evolve="${id}" ${n<2&&lv===1?'disabled':''}>EVOLUIR • 25</button></div></article>`}).join('')||'<p>Nenhum herói encontrado.</p>';root.querySelectorAll('[data-evolve]').forEach(b=>b.onclick=()=>{const id=b.dataset.evolve;if((data.ownedHeroes[id]||0)<2||data.essence<25){toast('Necessita cópia e 25 essências.');return;}data.ownedHeroes[id]--;data.essence-=25;data.heroLevels[id]=(data.heroLevels[id]||1)+1;save();renderCollection();renderBuild();toast('Herói evoluído!')});}

$('#startWave').onclick=startWave;$('#pauseBtn').onclick=()=>{G.paused=!G.paused;$('#pauseBtn').textContent=G.paused?'▶':'Ⅱ';};$('#speedBtn').onclick=()=>{G.speed=G.speed===1?2:G.speed===2?3:1;$('#speedBtn').textContent=G.speed+'×';};
function openAdmin(){const auth=!!data.admin;$('.admin-modal form').hidden=auth;$('.admin-modal #adminTools').hidden=!auth;if(auth){$('#adminTools').hidden=false;$('#adminTools').classList.add('admin-tool-grid');$('#adminTools').innerHTML='<button data-admin="gold">+5.000 moedas</button><button data-admin="gems">+500 gemas</button><button data-admin="lives">Vida cheia</button><button data-admin="reset">Reiniciar progresso</button>';$('#adminTools').querySelectorAll('[data-admin]').forEach(b=>b.onclick=()=>adminAction(b.dataset.admin));}$('#adminBackdrop').classList.add('show');}
function adminAction(action){if(action==='gold')data.gold+=5000;if(action==='gems')data.gems+=500;if(action==='lives')G.lives=20;if(action==='reset'){localStorage.removeItem(KEY);data={...initial};G.units=[];G.enemies=[];G.lives=20;G.wave=0;G.running=false;}save();wallet();renderBuild();renderCollection();toast(action==='reset'?'Progresso reiniciado.':'Recurso aplicado.');}
$('#adminOpen').onclick=openAdmin;$('#adminLink').onclick=openAdmin;$('#adminClose').onclick=()=>$('#adminBackdrop').classList.remove('show');$('#adminForm').onsubmit=e=>{e.preventDefault();if($('#adminPassword').value==='1919'){data.admin=true;save();openAdmin();$('#adminMessage').textContent='Acesso concedido. Controles ativos.';}else $('#adminMessage').textContent='Senha incorreta.';};

wallet();renderBuild();renderShop();renderBanners();renderCollection();initCanvas();
